html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.2f}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set p = pay_slip(doc) -%}
<style>
.lpl-slip { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #000; line-height: 1.35;
  width: 350px; border: 1px solid #000; padding: 26px 22px 30px; }
.lpl-slip table { width: 100%; border-collapse: collapse; }
.lpl-slip td, .lpl-slip th { padding: 1px 0; vertical-align: top; text-align: left; font-weight: normal; }
.lpl-slip .who td.logo { width: 92px; text-align: right; padding-top: 12px; }
.lpl-slip .who td.logo img { max-width: 88px; max-height: 46px; }
.lpl-slip .id td { padding: 2px 0; text-transform: uppercase; }
.lpl-slip .id td.k { width: 96px; }
.lpl-slip .id td.c { width: 10px; }
.lpl-slip .pay { margin-top: 8px; }
.lpl-slip .pay td.n, .lpl-slip .pay th.n { text-align: right; width: 104px; }
.lpl-slip .pay td.h, .lpl-slip .pay th.h { text-align: right; width: 56px; }
.lpl-slip .pay td.name { text-transform: uppercase; }
.lpl-slip .pay tr.head th { font-weight: bold; border-top: 1px dashed #000; border-bottom: 1px dashed #000;
  padding: 4px 0; }
.lpl-slip .pay tr.first td { padding-top: 4px; }
.lpl-slip .pay tr.sum td { font-weight: bold; padding-bottom: 4px; }
.lpl-slip .pay tr.total td { font-weight: bold; border-top: 1px dashed #000; border-bottom: 1px dashed #000;
  padding: 4px 0; }
.lpl-slip .pay tr.net td { font-weight: bold; padding-top: 5px; }
.lpl-slip .days { margin-top: 20px; }
.lpl-slip .days td { padding: 3px 0; }
.lpl-slip .days td.by { font-weight: bold; padding-bottom: 6px; }
.lpl-slip .days td.k { width: 96px; font-weight: bold; }
.lpl-slip .days td.c { width: 22px; }
</style>
<div class="lpl-slip">
<table class="who"><tr><td>
<table class="id">
<tr><td class="k">NAME</td><td class="c">:</td><td>{{ v(p.employee_name) }}</td></tr>
<tr><td class="k">DEPT</td><td class="c">:</td><td>{{ v(p.department) }}</td></tr>
<tr><td class="k">PAYROLL NO.</td><td class="c">:</td><td>{{ v(p.payroll_no) }}</td></tr>
<tr><td class="k">PAY SLIP FOR</td><td class="c">:</td><td>{{ v(p.slip_for) }}</td></tr>
<tr><td class="k">DESIGNATION</td><td class="c">:</td><td>{{ v(p.designation) }}</td></tr>
<tr><td class="k">CATEGORY</td><td class="c">:</td><td>{{ v(p.category) }}</td></tr>
<tr><td class="k">PLANT</td><td class="c">:</td><td>{{ v(p.plant) }}</td></tr>
</table>
</td><td class="logo">{% if logo %}<img src="{{ logo }}">{% endif %}</td></tr></table>
<table class="pay">
<tr class="head"><th>P A Y M E N T S</th><th class="n">AMOUNT</th><th class="h">HOURS</th></tr>
{%- for line in p.payments %}
<tr{% if loop.index == 1 %} class="first"{% endif %}><td class="name">{{ v(line.name) }}</td><td class="n">{{ money(line.amount) }}</td><td class="h">{% if line.hours %}{{ num(line.hours) }}{% endif %}</td></tr>
{%- endfor %}
<tr class="sum"><td>GROSS PAY</td><td class="n">{{ money(p.gross) }}</td><td class="h"></td></tr>
<tr class="head"><th>DEDUCTIONS</th><th class="n">AMOUNT</th><th class="h">HOURS</th></tr>
{%- for line in p.deductions %}
<tr{% if loop.index == 1 %} class="first"{% endif %}><td class="name">{{ v(line.name) }}</td><td class="n">{{ money(line.amount) }}</td><td class="h"></td></tr>
{%- endfor %}
<tr class="total"><td>TOTAL</td><td class="n">{{ money(p.total_deductions) }}</td><td class="h"></td></tr>
<tr class="net"><td>N E T &nbsp; P A Y</td><td class="n">{{ money(p.net) }}</td><td class="h"></td></tr>
<tr class="net"><td>NET PAY R/o</td><td class="n">{{ money(p.rounded) }}</td><td class="h"></td></tr>
</table>
<table class="days">
<tr><td class="by" colspan="3">PAYMENT BY : {{ v(p.payment_by) }}</td></tr>
<tr><td class="k">Paid Days</td><td class="c">=</td><td>{{ num(p.paid_days) }}</td></tr>
<tr><td class="k">Working Days</td><td class="c">=</td><td>{{ num(p.working_days) }}</td></tr>
<tr><td class="k">Holidays</td><td class="c">=</td><td>{{ num(p.holidays) }}</td></tr>
<tr><td class="k">Absent Amount</td><td class="c">=</td><td>{{ money(p.absent_amount) }}</td></tr>
<tr><td class="k">Leave Taken</td><td class="c">=</td><td>{{ num(p.leave_taken) }}</td></tr>
<tr><td class="k">Absent Days</td><td class="c">=</td><td>{{ num(p.absent_days) }}</td></tr>
</table>
</div>
